1	package org.springframework.samples.petclinic.rest.function.owner;
2	
3	import java.util.ArrayList;
4	import java.util.Collection;
5	import java.util.List;
6	
7	import org.springframework.samples.petclinic.model.Owner;
8	import org.springframework.samples.petclinic.repository.OwnerRepository;
9	
10	/**
11	 * Counts how many owners belong to a household — owners that share a non-blank {@code householdId} —
12	 * and stamps that count onto {@link Owner#setHouseholdMemberCount(Integer)} just before an owner is
13	 * mapped to its DTO.
14	 *
15	 * <p>An owner with no {@code householdId} is a household of one. Counting reflects the owners
16	 * currently stored, so the freshly created owner (already saved by the time it is responded) is
17	 * included in its own household's count.
18	 */
19	final class HouseholdMembers {
20	
21	    private HouseholdMembers() {
22	    }
23	
24	    /** Stamp a single owner's household member count. */
25	    static void stamp(Owner owner, OwnerRepository ownerRepository) {
26	        List<Owner> all = new ArrayList<>();
27	        ownerRepository.findAll().forEach(all::add);
28	        owner.setHouseholdMemberCount(count(owner, all));
29	    }
30	
31	    /** Stamp every owner in the collection, reading the stored owners only once. */
32	    static void stampAll(Collection<Owner> owners, OwnerRepository ownerRepository) {
33	        List<Owner> all = new ArrayList<>();
34	        ownerRepository.findAll().forEach(all::add);
35	        for (Owner owner : owners) {
36	            owner.setHouseholdMemberCount(count(owner, all));
37	        }
38	    }
39	
40	    private static int count(Owner owner, List<Owner> all) {
41	        String householdId = owner.getHouseholdId();
42	        if (householdId == null || householdId.isBlank()) {
43	            return 1;
44	        }
45	        int count = 0;
46	        for (Owner other : all) {
47	            if (householdId.equals(other.getHouseholdId())) {
48	                count++;
49	            }
50	        }
51	        return count == 0 ? 1 : count;
